/* jQuery 3.6.0 - Basic functionality */
window.jQuery = window.$ = function(selector) {
  if (typeof selector === 'string') {
    return {
      elements: document.querySelectorAll(selector),
      ready: function(callback) {
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', callback);
        } else {
          callback();
        }
      },
      click: function(handler) {
        this.elements.forEach(el => el.addEventListener('click', handler));
        return this;
      },
      on: function(event, handler) {
        this.elements.forEach(el => el.addEventListener(event, handler));
        return this;
      },
      val: function(value) {
        if (value !== undefined) {
          this.elements.forEach(el => el.value = value);
          return this;
        }
        return this.elements[0] ? this.elements[0].value : '';
      },
      text: function(text) {
        if (text !== undefined) {
          this.elements.forEach(el => el.textContent = text);
          return this;
        }
        return this.elements[0] ? this.elements[0].textContent : '';
      },
      html: function(html) {
        if (html !== undefined) {
          this.elements.forEach(el => el.innerHTML = html);
          return this;
        }
        return this.elements[0] ? this.elements[0].innerHTML : '';
      },
      hide: function() {
        this.elements.forEach(el => el.style.display = 'none');
        return this;
      },
      show: function() {
        this.elements.forEach(el => el.style.display = '');
        return this;
      },
      addClass: function(className) {
        this.elements.forEach(el => el.classList.add(className));
        return this;
      },
      removeClass: function(className) {
        this.elements.forEach(el => el.classList.remove(className));
        return this;
      },
      toggleClass: function(className) {
        this.elements.forEach(el => el.classList.toggle(className));
        return this;
      }
    };
  } else if (typeof selector === 'function') {
    // Document ready
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', selector);
    } else {
      selector();
    }
  }
};